CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE circles(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,level VARCHAR(80),description TEXT,days VARCHAR(150),time VARCHAR(20),duration VARCHAR(50),location VARCHAR(255),created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE enrollments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,circle_id INT NOT NULL,status ENUM('active','pending','rejected') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_enrollment(user_id,circle_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(circle_id) REFERENCES circles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,enrollment_id INT NOT NULL,date DATE NOT NULL,status ENUM('present','absent') NOT NULL,recorded_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_day(enrollment_id,date),FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE,FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE materials(id INT AUTO_INCREMENT PRIMARY KEY,circle_id INT NOT NULL,filename VARCHAR(255) NOT NULL,filepath VARCHAR(255) NOT NULL,uploaded_by INT NULL,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(circle_id) REFERENCES circles(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
